"""Secrets Manager secrets whose values are generated by AWS, never committed."""

from __future__ import annotations

import re

from aws_cdk import aws_secretsmanager as secretsmanager
from constructs import Construct

from cognitech_cdk.common.environment import Environment
from cognitech_cdk.constructs.secrets import Secrets, SecretsProps
from cognitech_cdk.stacks.base import EnvironmentStack


def _logical(name: str) -> str:
    return "".join(part[:1].upper() + part[1:] for part in re.split(r"[^A-Za-z0-9]+", name) if part)


class SecretsStack(EnvironmentStack):
    def __init__(
        self,
        scope: Construct,
        construct_id: str,
        *,
        environment: Environment,
        props: SecretsProps,
        **kwargs,
    ) -> None:
        super().__init__(scope, construct_id, environment=environment, **kwargs)
        built = Secrets(self, "Secrets", props=props, naming=self.resource_name)
        self.secrets: dict[str, secretsmanager.ISecret] = dict(built.secrets)
        for key, secret in built.secrets.items():
            logical = _logical(key)
            self.output(f"{logical}SecretArn", secret.secret_arn, f"{key}-secret-arn")
            self.output(f"{logical}SecretName", secret.secret_name, f"{key}-secret-name")
